const $=id=>document.getElementById(id);let db,selectedType='Other Document',files={front:null,back:null},urls=[],currentPage='home',historyStack=[],instantScanPages=[],lastGeneratedScan=null,cameraStream=null,cameraFacing='environment',capturedCameraBlob=null,cameraTarget='instant',smartScanFile=null,smartScanResult=null,smartScanPreviewUrl='',smartScanPreviewMarkup='',smartCustomFolders=[];
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function toast(t){const e=$('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
function toggleNotifPanel(){const p=$('notifPanel');p.classList.toggle('show')}
document.addEventListener('click',e=>{const n=$('notifPanel');if(n&&n.classList.contains('show')){const inPanel=n.contains(e.target);const onBtn=e.target.closest('.iconBtn');if(!inPanel&&!onBtn)n.classList.remove('show')}const p=$('profileMenu');if(p&&p.classList.contains('show')){const inMenu=p.contains(e.target);const onProfile=e.target.closest('#profileChip');if(!inMenu&&!onProfile)p.classList.remove('show')}});
function authState(){try{return JSON.parse(localStorage.getItem('docsphere_auth')||'null')}catch{return null}}
function renderAuth(){const a=authState();const logged=!!(a&&a.name);$('profileName').textContent=logged?a.name:tr('user');$('profileAvatar').textContent=logged?a.name.trim().charAt(0).toUpperCase():'U';$('profileStateText').textContent=logged?tr('loggedInAs'):tr('notLoggedIn');$('menuAccountState').textContent=logged?tr('loggedIn'):tr('notLoggedIn');$('menuAccountName').textContent=logged?a.name:tr('guestUser');$('loginMenuBtn').classList.toggle('hidden',logged);$('logoutMenuBtn').classList.toggle('hidden',!logged)}
function updateProfileName(docs){renderAuth()}
function siteSettings(){try{return JSON.parse(localStorage.getItem('dochub_settings')||'null')||{theme:'ocean',mode:'dark'}}catch{return{theme:'ocean',mode:'dark'}}}
function applySiteSettings(){const s=siteSettings();const mode=s.mode||'dark';document.body.dataset.theme=s.theme||'ocean';document.body.dataset.mode=mode;const b=$('modeButton'),i=$('modeIcon'),l=$('modeLabel'),h=$('modeHelp');if(b){b.classList.toggle('dark',mode==='dark');b.classList.toggle('light',mode==='light')}if(i)i.textContent=mode==='dark'?'🌙':'☀️';if(l)l.textContent=mode==='dark'?tr('dark'):tr('light');if(h)h.textContent=mode==='dark'?tr('darkActive'):tr('lightActive');document.querySelectorAll('[data-theme-choice]').forEach(btn=>btn.classList.toggle('active',btn.dataset.themeChoice===(s.theme||'ocean')))}
const DFAB_THEME_VERSION='dochub_dfab_blue_v1';(function(){try{if(!localStorage.getItem(DFAB_THEME_VERSION)){const cur=siteSettings();localStorage.setItem('dochub_settings',JSON.stringify({...cur,theme:'ocean',mode:'dark'}));localStorage.setItem(DFAB_THEME_VERSION,'1')}}catch(e){}})();
function saveSiteSettings(next){const s={...siteSettings(),...next};localStorage.setItem('dochub_settings',JSON.stringify(s));applySiteSettings()}
function setSiteTheme(theme){saveSiteSettings({theme});toast('Theme changed')}
function toggleAppearanceMode(){const s=siteSettings();const next=(s.mode||'dark')==='dark'?'light':'dark';saveSiteSettings({mode:next});toast(next==='dark'?'🌙 Dark mode on':'☀️ Light mode on')}
function openSettingsModal(){$('profileMenu').classList.remove('show');applySiteSettings();applyAdvancedSettings();$('settingsModal').classList.add('show');updateStorageUsage()}
function closeSettingsModal(){$('settingsModal').classList.remove('show')}
const settingsModal=$('settingsModal');if(settingsModal){settingsModal.addEventListener('click',e=>{if(e.target===settingsModal)closeSettingsModal()})}
function uiPrefs(){try{return JSON.parse(localStorage.getItem('dochub_user_prefs')||'null')||{language:'en',notifications:{expiry:true,renewal:true,health:true},biometric:false,pin:''}}catch{return{language:'en',notifications:{expiry:true,renewal:true,health:true},biometric:false,pin:''}}}
function saveUiPrefs(next){const cur=uiPrefs();const merged={...cur,...next,notifications:{...cur.notifications,...(next.notifications||{})}};localStorage.setItem('dochub_user_prefs',JSON.stringify(merged));return merged}
