const TYPE_LANG={ta:{'Aadhaar Card':'ஆதார் அட்டை','PAN Card':'PAN அட்டை','Driving Licence':'ஓட்டுநர் உரிமம்','Voter ID':'வாக்காளர் அட்டை','Passport':'பாஸ்போர்ட்','RC Book / Card':'RC புத்தகம் / அட்டை','Insurance':'காப்பீடு','Education Certificate':'கல்வி சான்றிதழ்','Medical Document':'மருத்துவ ஆவணம்','Bank Document':'வங்கி ஆவணம்','Property Document':'சொத்து ஆவணம்','Other Document':'மற்ற ஆவணம்'},hi:{'Aadhaar Card':'आधार कार्ड','PAN Card':'PAN कार्ड','Driving Licence':'ड्राइविंग लाइसेंस','Voter ID':'वोटर आईडी','Passport':'पासपोर्ट','RC Book / Card':'RC बुक / कार्ड','Insurance':'बीमा','Education Certificate':'शिक्षा प्रमाणपत्र','Medical Document':'चिकित्सा दस्तावेज़','Bank Document':'बैंक दस्तावेज़','Property Document':'संपत्ति दस्तावेज़','Other Document':'अन्य दस्तावेज़'},kn:{'Aadhaar Card':'ಆಧಾರ್ ಕಾರ್ಡ್','PAN Card':'PAN ಕಾರ್ಡ್','Driving Licence':'ಚಾಲನಾ ಪರವಾನಗಿ','Voter ID':'ಮತದಾರ ಗುರುತಿನ ಚೀಟಿ','Passport':'ಪಾಸ್‌ಪೋರ್ಟ್','RC Book / Card':'RC ಪುಸ್ತಕ / ಕಾರ್ಡ್','Insurance':'ವಿಮೆ','Education Certificate':'ಶಿಕ್ಷಣ ಪ್ರಮಾಣಪತ್ರ','Medical Document':'ವೈದ್ಯಕೀಯ ದಾಖಲೆ','Bank Document':'ಬ್ಯಾಂಕ್ ದಾಖಲೆ','Property Document':'ಆಸ್ತಿ ದಾಖಲೆ','Other Document':'ಇತರೆ ದಾಖಲೆ'}};
function tr(key){const p=uiPrefs();return (LANG[p.language]||LANG.en)[key]||LANG.en[key]||key}
function applyLanguage(){const p=uiPrefs(),t=LANG[p.language]||LANG.en;document.documentElement.lang=p.language||'en';document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(t[k]!=null)el.innerHTML=t[k]});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const k=el.dataset.i18nPlaceholder;if(t[k]!=null)el.placeholder=t[k]});const map=[['heroTitle','hero'],['storeTitle','store'],['dashboardTitle','dashboard'],['vaultTitle','vault'],['searchTitle','search']];for(const [id,key] of map){const el=$(id);if(el)el.innerHTML=t[key]}const sel=$('languageSelect');if(sel)sel.value=p.language||'en';renderAuth();applySiteSettings();renderTypes()}
function setLanguage(lang){saveUiPrefs({language:lang});applyLanguage();toast('Language changed')}
function applyAdvancedSettings(){const p=uiPrefs();applyLanguage();const e=$('prefExpiry'),r=$('prefRenewal'),h=$('prefHealth'),b=$('biometricToggle');if(e)e.checked=p.notifications.expiry!==false;if(r)r.checked=p.notifications.renewal!==false;if(h)h.checked=p.notifications.health!==false;if(b)b.checked=!!p.biometric;const pin=$('appPinInput');if(pin)pin.value=p.pin||'';const a=authState();const id=$('securityLoginId');if(id){id.value=a?.id||'';id.disabled=!a}}
function saveNotificationPrefs(){const notifications={expiry:$('prefExpiry').checked,renewal:$('prefRenewal').checked,health:$('prefHealth').checked};saveUiPrefs({notifications});renderAll();toast('Notification preferences saved')}
function saveLoginIdentifier(){const a=authState();if(!a){toast('Log in first');return}const id=normalizeLoginId($('securityLoginId').value);if(!(isEmail(id)||isPhone(id))){toast('Enter a valid email or mobile number');return}localStorage.setItem('docsphere_auth',JSON.stringify({...a,id,channel:isEmail(id)?'email':'SMS'}));renderAuth();toast('Login contact updated')}
function saveAppPin(){const pin=$('appPinInput').value.trim();if(pin&&!/^\d{4}$/.test(pin)){toast('PIN must be exactly 4 digits');return}saveUiPrefs({pin});toast(pin?'App PIN saved':'App PIN removed')}
function saveBiometricPreference(enabled){saveUiPrefs({biometric:enabled});toast(enabled?'Biometric preference enabled':'Biometric preference disabled')}
function blobToDataURL(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)})}
function dataURLToBlob(dataURL){const [head,data]=dataURL.split(',');const mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';const bin=atob(data);const arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);return new Blob([arr],{type:mime})}
function downloadJson(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});downloadBlob(blob,name)}
async function buildBackupPayload(){const docs=await docsAll();const out=[];for(const d of docs){out.push({...d,blob:await blobToDataURL(d.blob)})}return{version:1,exportedAt:new Date().toISOString(),auth:authState(),settings:siteSettings(),prefs:uiPrefs(),docs:out}}
async function createBackup(){try{const data=await buildBackupPayload();downloadJson(data,'DocHub_Backup.json');toast('Backup created')}catch(e){toast('Could not create backup')}}
async function exportAllData(){try{const data=await buildBackupPayload();downloadJson({...data,type:'DocHub full data export'},'DocHub_All_Data.json');toast('All data exported')}catch(e){toast('Could not export data')}}
async function restoreBackup(file){if(!file)return;try{const text=await file.text();const data=JSON.parse(text);if(!Array.isArray(data.docs))throw new Error('Invalid backup');if(data.auth)localStorage.setItem('docsphere_auth',JSON.stringify(data.auth));if(data.settings)localStorage.setItem('dochub_settings',JSON.stringify(data.settings));if(data.prefs)localStorage.setItem('dochub_user_prefs',JSON.stringify(data.prefs));for(const d of data.docs){const blob=typeof d.blob==='string'?dataURLToBlob(d.blob):null;if(!blob)continue;await addDoc({...d,blob,id:d.id||Date.now()+Math.random()})}applySiteSettings();applyAdvancedSettings();renderAuth();await renderAll();toast('Backup restored')}catch(e){toast('Invalid or unreadable backup')}finally{$('restoreBackupInput').value=''}}
async function updateStorageUsage(){const docs=await docsAll();const bytes=docs.reduce((n,d)=>n+(Number(d.size)||d.blob?.size||0),0);$('storageUsedText').textContent=fmt(bytes)+' used';$('storageDocCount').textContent=docs.length+' document'+(docs.length===1?'':'s');const max=100*1024*1024;$('storageBarFill').style.width=Math.min(100,(bytes/max)*100)+'%';$('storageHint').textContent='Storage is calculated from PDFs saved in this browser. Bar shown against a 100 MB reference.'}
async function deleteAccountAndData(){if(!confirm('Delete your local DocHub account, all saved documents and settings? This cannot be undone.'))return;try{const docs=await docsAll();for(const d of docs)await delDoc(d.id);localStorage.removeItem('docsphere_auth');localStorage.removeItem('dochub_settings');localStorage.removeItem('dochub_user_prefs');sessionStorage.removeItem('docsphere_pending_otp');applySiteSettings();applyAdvancedSettings();renderAuth();await renderAll();closeSettingsModal();toast('Account and local data deleted')}catch(e){toast('Could not delete all data')}}
function toggleProfileMenu(){const p=$('profileMenu');p.classList.toggle('show');$('notifPanel').classList.remove('show')}
function showLoginStep(n){document.querySelectorAll('#loginModal .step').forEach(s=>s.classList.remove('active'));$('loginStep'+n).classList.add('active')}
function openLoginModal(){$('profileMenu').classList.remove('show');const a=authState();$('loginName').value=a?.name||'';$('loginId').value=a?.id||'';$('loginOtp').value='';showLoginStep(1);$('loginModal').classList.add('show')}
function closeLoginModal(){$('loginModal').classList.remove('show');sessionStorage.removeItem('docsphere_pending_otp')}
function normalizeLoginId(v){return String(v||'').trim()}
function isEmail(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)}
function isPhone(v){return /^\+?[0-9]{10,15}$/.test(v.replace(/[\s-]/g,''))}
function maskDestination(v){if(isEmail(v)){const [u,d]=v.split('@');return (u.slice(0,2)||u)+'***@'+d}const p=v.replace(/[\s-]/g,'');return p.slice(0,2)+'******'+p.slice(-2)}
function generateOtp(){return String(Math.floor(100000+Math.random()*900000))}
function sendLoginOtp(){const name=$('loginName').value.trim(),id=normalizeLoginId($('loginId').value);if(!name){toast('Enter your name');return}if(!(isEmail(id)||isPhone(id))){toast('Enter a valid email or mobile number');return}const otp=generateOtp(),channel=isEmail(id)?'email':'SMS';sessionStorage.setItem('docsphere_pending_otp',JSON.stringify({name,id,otp,channel,createdAt:Date.now()}));$('otpDestination').innerHTML=`OTP sent to your <b>${channel}</b>: ${esc(maskDestination(id))}`;$('otpDemoNote').innerHTML=`<b>Prototype note:</b> Real ${channel} delivery needs a backend service. For this local demo, your test OTP is <b>${otp}</b>.`;$('loginOtp').value='';showLoginStep(2);toast('OTP generated')}
function resendLoginOtp(){sendLoginOtp()}
function verifyLoginOtp(){let pending=null;try{pending=JSON.parse(sessionStorage.getItem('docsphere_pending_otp')||'null')}catch{}if(!pending){toast('Send OTP first');showLoginStep(1);return}if(Date.now()-pending.createdAt>5*60*1000){toast('OTP expired. Resend OTP');showLoginStep(1);return}const entered=$('loginOtp').value.trim();if(!/^\d{6}$/.test(entered)){toast('Enter the 6-digit OTP');return}if(entered!==pending.otp){toast('Incorrect OTP');return}localStorage.setItem('docsphere_auth',JSON.stringify({name:pending.name,id:pending.id,verified:true,channel:pending.channel,verifiedAt:Date.now()}));sessionStorage.removeItem('docsphere_pending_otp');renderAuth();closeLoginModal();toast('OTP verified. Logged in')}
function logoutUser(){localStorage.removeItem('docsphere_auth');sessionStorage.removeItem('docsphere_pending_otp');$('profileMenu').classList.remove('show');renderAuth();toast('Logged out')}
function updateNotifications(docs){const prefs=uiPrefs().notifications||{};const expiring=docs.filter(d=>{const n=daysUntil(d.expiry);return prefs.renewal!==false&&n!==null&&n>=0&&n<=30&&d.docType!=='Medical Document'});const expired=docs.filter(d=>{const n=daysUntil(d.expiry);return prefs.expiry!==false&&n!==null&&n<0});const health=docs.filter(d=>{const n=daysUntil(d.expiry);return prefs.health!==false&&d.docType==='Medical Document'&&n!==null&&n>=0&&n<=30});const total=expiring.length+expired.length+health.length;const badge=$('notifBadge');badge.textContent=String(total);badge.classList.toggle('hide',total===0);const list=$('notifList');if(!total){list.innerHTML='<div class="notice">No alerts right now.</div>';return}list.innerHTML=[...expired.map(d=>`<div class="notifItem"><b>${esc(d.docType)} expired</b><small>${esc(d.person)} · ${esc(d.expiry||'')}</small></div>`),...expiring.map(d=>{const n=daysUntil(d.expiry);return `<div class="notifItem"><b>${esc(d.docType)} renewal due soon</b><small>${esc(d.person)} · ${n} day${n===1?'':'s'} left</small></div>`}),...health.map(d=>{const n=daysUntil(d.expiry);return `<div class="notifItem"><b>Health follow-up reminder</b><small>${esc(d.person)} · ${esc(d.docType)} · ${n} day${n===1?'':'s'} left</small></div>`})].join('')}
function go(page,push=true){if(page===currentPage)return;if(push)historyStack.push(currentPage);currentPage=page;document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));$('page-'+page).classList.add('active');window.scrollTo({top:0,behavior:'smooth'});if(page==='dashboard'||page==='vault')renderAll();if(page==='history')renderHistory()}
function goBack(){if(!historyStack.length){go('home',false);return}const prev=historyStack.pop();currentPage=prev;document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));$('page-'+prev).classList.add('active');window.scrollTo({top:0,behavior:'smooth'});if(prev==='dashboard'||prev==='vault')renderAll();if(prev==='history')renderHistory()}
function renderTypes(){const lang=uiPrefs().language||'en',names=TYPE_LANG[lang]||{};$('docTypes').innerHTML=PERSONAL_TYPES.map(t=>`<div class="card typeCard" onclick="openUpload('${esc(t.name)}')"><div class="typeIcon">${t.iconData?`<img class=\"realDocIcon\" src=\"${t.iconData}\" alt=\"${esc(t.name)} icon\">`:t.iconPath?`<img class=\"realDocIcon\" src=\"${esc(t.iconPath)}\" alt=\"${esc(t.name)} icon\">`:esc(t.icon)}</div><h4>${esc(names[t.name]||t.name)}</h4><p>${esc(t.desc)}</p></div>`).join('');let opts=`<optgroup label="Personal Documents">${PERSONAL_TYPES.map(t=>`<option value="${esc(t.name)}">${esc(names[t.name]||t.name)}</option>`).join('')}</optgroup>`;for(const g of COMPANY_GROUPS){opts+=`<optgroup label="${esc(g.name)}">${g.docs.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</optgroup>`}$('docTypeSelect').innerHTML=opts;renderCompanyGroups()}
function renderCompanyGroups(){const box=$('companyGroups');if(!box)return;box.innerHTML=COMPANY_GROUPS.map((g,i)=>`<div class="card companyGroupCard" id="companyGroup-${i}" onclick="openCompanyGroup(${i})"><span class="companyGroupCount">${g.docs.length} types</span><div class="companyGroupIcon">${g.icon}</div><h3>${esc(g.name)}</h3><p>${esc(g.desc)}</p></div>`).join('')}
function openCompanyGroup(index){const g=COMPANY_GROUPS[index];if(!g)return;document.querySelectorAll('.companyGroupCard').forEach((el,i)=>el.classList.toggle('active',i===index));$('companyDocPanel').classList.remove('hidden');$('companyPanelTitle').textContent=g.name;$('companyPanelHint').textContent=`${g.docs.length} document types · tap one to add`;$('companyDocGrid').innerHTML=g.docs.map((name,i)=>`<button class="companyDocItem" onclick="openUpload('${esc(name)}')"><span class="companyDocNo">${i+1}</span><span>${esc(name)}</span></button>`).join('');$('companyDocPanel').scrollIntoView({behavior:'smooth',block:'nearest'})}
function isCompanyType(name){return COMPANY_TYPES.some(t=>t.name===name)}
function handleDocTypeChange(){const val=$('docTypeSelect').value,isOther=val==='Other Document',company=isCompanyType(val);$('customDocFields').classList.toggle('hidden',!isOther);if(!isOther){$('customDocName').value='';$('customSides').value='1'}const lbl=$('personNameLabel');if(lbl)lbl.textContent=company?'Company / Department / Owner name':tr('personName');$('personName').placeholder=company?'Enter company, department or owner name':tr('enterFullName');if($('frontQuickPreview'))renderQuickUploadPreview()}
function getSelectedConfig(){const base=$('docTypeSelect').value;if(base==='Other Document'){const custom=$('customDocName').value.trim();return{name:custom||'Other Document',sides:Number($('customSides').value)||1}}return TYPES.find(x=>x.name===base)||TYPES[TYPES.length-1]}
function openAddDocumentsModal(){$('addDocumentsModal').classList.add('show')}
function closeAddDocumentsModal(){$('addDocumentsModal').classList.remove('show')}
$('addDocumentsModal')?.addEventListener('click',e=>{if(e.target===$('addDocumentsModal'))closeAddDocumentsModal()})
function startManualAdd(){closeAddDocumentsModal();openGenericUpload()}
function resetSmartScan(){smartScanFile=null;smartScanResult=null;smartScanPreviewUrl='';smartScanPreviewMarkup='';$('smartOwner').value='';$('smartHint').value='';$('smartUploadInput').value='';$('smartCameraInput').value='';$('smartSaveBtn').disabled=true;$('smartNewFolderBox').classList.add('hidden');$('smartNewFolderName').value='';renderSmartUploadChoicePreview(null);$('smartScanState').innerHTML='<b>No document selected</b><div class="muted" style="margin-top:5px">Capture or upload a document to analyse it.</div>'}
function openSmartScanModal(){closeAddDocumentsModal();resetSmartScan();$('smartScanModal').classList.add('show')}
function closeSmartScanModal(){$('smartScanModal').classList.remove('show');smartScanPreviewUrl='';smartScanPreviewMarkup='';smartScanFile=null;smartScanResult=null}
$('smartScanModal')?.addEventListener('click',e=>{if(e.target===$('smartScanModal'))closeSmartScanModal()})
